css:
.loader{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.loader i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.loader{position:relative}
.loader i{position:absolute;animation:td-fire var(--loader-speed, 1.5s) infinite ease-out}
.loader i:nth-child(2){animation-delay:calc(var(--loader-speed, 1.5s) / 3)}
.loader i:nth-child(3){animation-delay:calc(var(--loader-speed, 1.5s) / 1.5)}
@keyframes td-fire{
  0%{transform:translateY(calc(var(--loader-size, 56px) / 3)) scale(1);opacity:1}
  100%{transform:translateY(calc(var(--loader-size, 56px) / -3)) scale(.3);opacity:0}
}
